// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.executorimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.brain.skill.executor.SystemOperationExecutorimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.handler.SystemOperationHandlerimport com.roshan.persona.system.util.HardwareExceptionMapperimport com.roshan.persona.system.util.HardwareHeavyOperationimport com.roshan.persona.system.util.ThermalGateimport kotlinx.coroutines.asyncimport kotlinx.coroutines.awaitAllimport kotlinx.coroutines.coroutineScopeimport timber.log.Timber/** * NOUS — System Operation Executor Impl (Module 10 v2 — main entry point). * * Implements Brain's [SystemOperationExecutor] interface. Routes each * [SystemOperation] to the matching [SystemOperationHandler], with these * v2 enhancements (per strategy §"Architecture"): * *  1. **Pre-state capture** (Review 2 Fix A) — every reversible operation *     captures its pre-state via the handler. Pre-state is stored for *     undo/rollback. * *  2. **Idempotent skip** (Review 2 Elite 1) — if the handler reports the *     device is already in the target state, the hardware call is skipped *     entirely (zero-flicker + battery save). * *  3. **Thermal gate** (Review 2 Elite 2) — hardware-heavy operations are *     pre-flight checked against [ThermalGate]. Refused at severe throttle. * *  4. **Hardware exception mapping** (Review 2 Fix C) — every handler call *     is wrapped; exceptions are mapped to [AppError.Hardware] subtypes. * *  5. **Composite unwrap** — `SystemOperation.Composite` is recursively *     unwrapped and dispatched via [AtomicBatchCoordinator] (Step 10.2 — *     until then, sequential dispatch with rollback). * *  6. **Permission gating** — executor checks `permissionChecker.areAllGranted` *     before dispatch. Missing permissions → `Result.Failure(Permission.Denied)`. * * ## Wiring (Step 10.9) * * This class replaces `FakeSystemOperationExecutor` in Brain's * `BuiltInSkillsModule` Hilt binding. Brain skills (TorchSkill, VolumeSkill, * etc.) call `executor.execute(operation)` — they don't know whether the * impl is fake or real. * * ## Testability * * Handlers are injected via a `Map<Class<SystemOperation>, SystemOperationHandler<*>>` * (Hilt multibinding). Tests inject a fake map. The executor itself is * testable without Robolectric for routing + pre-state + idempotent logic; * thermal gate + permission checker are interfaces. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Architecture, §Privacy & Security</a> */class SystemOperationExecutorImpl(    /**     * Handler registry — maps each [SystemOperation] subclass to its handler.     *     * Populated by Hilt multibinding in Step 10.9's SystemModule.     * Example entry: `SetTorch::class → TorchHandler`.     */    private val handlers: Map<Class<out SystemOperation>, SystemOperationHandler<*>>,    /** Permission checker — injected from Brain's PermissionChecker interface. */    private val permissionChecker: com.roshan.persona.brain.skill.router.PermissionChecker,    /** Thermal gate — null on devices without PowerManager (rare). */    private val thermalGate: ThermalGate,    /** Pre-state store — populated by [capturePreState] calls, used for undo. */    private val preStateStore: PreStateStore = InMemoryPreStateStore(),) : SystemOperationExecutor {    /**     * Execute a single operation.     *     * Pipeline:     *  1. Find handler for the operation type.     *  2. Check `handler.isAvailable()` — return Failure if not.     *  3. Check `permissionChecker.areAllGranted(handler.requiredPermissions)`.     *  4. Check `handler.isAlreadyInTargetState(operation)` — skip if true (idempotent).     *  5. Pre-flight thermal gate for hardware-heavy operations.     *  6. Capture pre-state.     *  7. Execute (wrapped in exception mapper).     *  8. Store pre-state for undo (only if execution succeeded and handler is reversible).     *     * Composite operations are unwrapped and dispatched as a batch.     *     * Returns only the [Result] — pre-state is captured internally and accessible     * via [executeWithPreState] for callers (e.g., [com.roshan.persona.system.di.SystemFacade])     * that need to push it to the undo stack WITHOUT re-capturing post-execution.     */    override suspend fun execute(operation: SystemOperation): Result<Unit> =        executeWithPreState(operation).result    /**     * Execute a single operation AND return the pre-state captured BEFORE     * execution (per Review 2 Fix A — pre-state, not inverse).     *     * This is the canonical entry point for callers that need to push the     * pre-state to the undo stack. Re-capturing the pre-state AFTER execution     * (the old `SystemFacade.pushToUndoStack` pattern) would capture the     * POST-state, making undo a no-op — see audit defect A.     *     * @return [ExecutionOutcome] containing the result, captured pre-state,     *         handler ID, description, and a `shouldPushToUndo` flag (false for     *         idempotent skips, failures, and non-reversible handlers).     */    @Suppress("UNCHECKED_CAST")    suspend fun executeWithPreState(operation: SystemOperation): ExecutionOutcome {        // Composite — unwrap and execute as a batch (sequential for v1 of Step 10.1;        // Step 10.2 will replace this with AtomicBatchCoordinator for parallel/rollback).        if (operation is SystemOperation.Composite) {            val results = executeAll(operation.operations)            val result: Result<Unit> = when (results) {                is Result.Success -> {                    val firstFailure = results.data.firstOrNull { it is Result.Failure }                    if (firstFailure is Result.Failure) {                        firstFailure as Result<Unit>                    } else {                        Result.Success(Unit, results.correlationId, results.durationNanos)                    }                }                is Result.Failure -> results                is Result.Partial -> Result.Success(Unit, results.correlationId, results.durationNanos)            }            // Composite operations don't push per-op pre-state to the undo stack            // (the batch coordinator manages its own rollback internally).            return ExecutionOutcome(                result = result,                operation = operation,                preState = null,                handlerId = null,                description = null,                shouldPushToUndo = false,            )        }        val startNanos = System.nanoTime()        val correlationId = CorrelationId.generate()        // 1. Find handler.        val handler = findHandler(operation)            ?: return ExecutionOutcome(                result = Result.Failure(                    error = AppError.Hardware.Unsupported(                        resource = operation::class.simpleName ?: "unknown",                        cause = null,                    ),                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                ).also {                    Timber.tag(TAG).w("No handler registered for ${operation::class.simpleName}")                },                operation = operation,                preState = null,                handlerId = null,                description = null,                shouldPushToUndo = false,            )        // 2. Check availability.        if (!handler.isAvailable()) {            return ExecutionOutcome(                result = Result.Failure(                    error = AppError.Hardware.Unavailable(                        resource = handler.displayName,                        cause = null,                    ),                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                ).also {                    Timber.tag(TAG).w("${handler.displayName} not available on this device.")                },                operation = operation,                preState = null,                handlerId = handler.id,                description = null,                shouldPushToUndo = false,            )        }        // 3. Check permissions.        val missing = permissionChecker.findMissing(handler.requiredPermissions)        if (missing.isNotEmpty()) {            return ExecutionOutcome(                result = Result.Failure(                    error = AppError.Permission.Denied(missing.first()),                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                ).also {                    Timber.tag(TAG).w("${handler.displayName} missing permissions: $missing")                },                operation = operation,                preState = null,                handlerId = handler.id,                description = null,                shouldPushToUndo = false,            )        }        // Cast handler to typed version (safe — registry guarantees type match).        val typedHandler = handler as SystemOperationHandler<SystemOperation>        // 4. Idempotent check — skip if already at target.        try {            if (typedHandler.isAlreadyInTargetState(operation)) {                Timber.tag(TAG).d("${handler.displayName}: already at target state, skipping (idempotent).")                return ExecutionOutcome(                    result = Result.Success(                        data = Unit,                        correlationId = correlationId,                        durationNanos = System.nanoTime() - startNanos,                        warnings = listOf("idempotent_skip"),                    ),                    operation = operation,                    preState = null,                    handlerId = handler.id,                    description = null,                    shouldPushToUndo = false,  // don't push idempotent skips to undo stack                )            }        } catch (t: Throwable) {            // Idempotent check failed (e.g., can't read current state) — proceed with execution.            Timber.tag(TAG).d("${handler.displayName}: idempotent check failed, proceeding.", t)        }        // 5. Thermal gate for hardware-heavy operations.        // Per spec: block torch + max-brightness at MODERATE (1.5), everything else at SEVERE (2.5).        if (operation.isHardwareHeavy()) {            val headroom = thermalGate.getThermalHeadroom()            if (headroom != null && !thermalGate.shouldAllowOperation(operation, headroom)) {                return ExecutionOutcome(                    result = thermalGate.thermalFailure(headroom).also {                        Timber.tag(TAG).w("${handler.displayName}: refused (thermal headroom=$headroom).")                    },                    operation = operation,                    preState = null,                    handlerId = handler.id,                    description = null,                    shouldPushToUndo = false,                )            }        }        // 6. Capture pre-state BEFORE execution (per Review 2 Fix A).        //    This is the critical fix — capture here, not after execution.        val preState = try {            typedHandler.capturePreState(operation)        } catch (t: Throwable) {            Timber.tag(TAG).w("${handler.displayName}: pre-state capture failed, continuing.", t)            null        }        // 7. Execute (wrapped in exception mapper).        val result = HardwareExceptionMapper.withMapping(handler.id) {            typedHandler.execute(operation)        }        // 8. Store pre-state for undo (only on success + reversible handler).        val isReversible = handler is com.roshan.persona.system.handler.ReversibleHandler<*>        if (result is Result.Success && preState != null && isReversible) {            preStateStore.store(operation, preState, handler.id)        }        // 9. Build description if reversible (for the undo UI).        val description: String? = if (isReversible) {            val revHandler = handler as com.roshan.persona.system.handler.ReversibleHandler<SystemOperation>            try {                revHandler.describeOperation(operation)            } catch (t: Throwable) {                Timber.tag(TAG).w("${handler.displayName}: describeOperation failed.", t)                operation::class.simpleName            }        } else {            null        }        return ExecutionOutcome(            result = result,            operation = operation,            preState = preState,            handlerId = if (isReversible) handler.id else null,            description = description,            shouldPushToUndo = result is Result.Success && isReversible && preState != null,        )    }    /**     * Execute multiple operations as a batch.     *     * **v1 of Step 10.1**: Sequential execution with best-effort rollback.     * **Step 10.2**: Will be replaced by [AtomicBatchCoordinator] with     * parallel/sequential dispatch + pre-state rollback.     */    override suspend fun executeAll(operations: List<SystemOperation>): Result<List<Result<Unit>>> {        val startNanos = System.nanoTime()        val correlationId = CorrelationId.generate()        val results = mutableListOf<Result<Unit>>()        val executedWithPreStates = mutableListOf<Pair<SystemOperation, Any?>>()        for (op in operations) {            val result = execute(op)            results.add(result)            if (result is Result.Failure) {                // v1: stop on first failure. Step 10.2 will rollback here.                Timber.tag(TAG).w("Batch failed at ${op::class.simpleName}: ${result.error}")                break            }            // Track for potential rollback (Step 10.2).            val preState = preStateStore.get(op)            if (preState != null) {                executedWithPreStates.add(op to preState.preState)            }        }        return Result.Success(            data = results,            correlationId = correlationId,            durationNanos = System.nanoTime() - startNanos,        )    }    // ──────────────────────────────────────────────────────────────────────    /** Find the handler registered for [operation]'s type. */    @Suppress("UNCHECKED_CAST")    internal fun findHandlerForOperation(operation: SystemOperation): SystemOperationHandler<*>? {        return findHandler(operation)    }    /** Find the handler registered for [operation]'s type. */    @Suppress("UNCHECKED_CAST")    private fun findHandler(operation: SystemOperation): SystemOperationHandler<*>? {        // Direct lookup by exact class.        handlers[operation::class.java]?.let { return it }        // Walk up supertypes (rare — SystemOperation is sealed, so direct match should work).        for ((cls, handler) in handlers) {            if (cls.isAssignableFrom(operation::class.java)) {                return handler            }        }        return null    }    /** True if the operation is hardware-heavy (per [HARDWARE_HEAVY_OPERATION_TYPES]). */    private fun SystemOperation.isHardwareHeavy(): Boolean {        val typeName = this::class.simpleName ?: return false        return typeName in HARDWARE_HEAVY_OPERATION_TYPES    }    private companion object {        private const val TAG = "SystemExecutor"    }}// ──────────────────────────────────────────────────────────────────────────/** * Stores pre-state snapshots for undo/rollback. * * v1 (Step 10.1): in-memory map keyed by operation. * Step 10.2: replaced by [com.roshan.persona.system.undo.PersistentUndoStack] * (Room DB backed, survives app restart). */interface PreStateStore {    suspend fun store(operation: SystemOperation, preState: Any?, handlerId: String)    suspend fun get(operation: SystemOperation): StoredPreState?    suspend fun remove(operation: SystemOperation)    suspend fun clear()}/** One stored pre-state entry. */data class StoredPreState(    val operation: SystemOperation,    val preState: Any?,    val handlerId: String,    val timestampMs: Long = System.currentTimeMillis(),)/** In-memory [PreStateStore] — for tests + Step 10.1. */class InMemoryPreStateStore : PreStateStore {    private val store = mutableMapOf<SystemOperation, StoredPreState>()    override suspend fun store(operation: SystemOperation, preState: Any?, handlerId: String) {        store[operation] = StoredPreState(operation, preState, handlerId)    }    override suspend fun get(operation: SystemOperation): StoredPreState? = store[operation]    override suspend fun remove(operation: SystemOperation) {        store.remove(operation)    }    override suspend fun clear() {        store.clear()    }}// ──────────────────────────────────────────────────────────────────────────/** * Outcome of executing a single operation via [SystemOperationExecutorImpl.executeWithPreState]. * * Carries the [result] PLUS the pre-state captured BEFORE execution (per Review 2 Fix A), * so the [com.roshan.persona.system.di.SystemFacade] can push it to the undo stack * WITHOUT re-capturing post-execution (which would capture the post-state — the bug * fixed by audit defect A). * * @param result          execution result (Success / Failure / Partial). * @param operation       the operation that was executed. * @param preState        state captured BEFORE execution (null for non-reversible handlers, *                        idempotent skips, or pre-execution failures). * @param handlerId       the executing handler's ID (null if no handler matched). * @param description     human-readable description for the undo UI (null if non-reversible). * @param shouldPushToUndo true iff this action should be pushed to the undo stack *                        (false for idempotent skips, failures, and non-reversible handlers). */data class ExecutionOutcome(    val result: Result<Unit>,    val operation: SystemOperation,    val preState: Any?,    val handlerId: String?,    val description: String?,    val shouldPushToUndo: Boolean,)// ──────────────────────────────────────────────────────────────────────────/** List of hardware-heavy operation types (re-exported for executor use). */val HARDWARE_HEAVY_OPERATION_TYPES: Set<String> =    com.roshan.persona.system.util.HARDWARE_HEAVY_OPERATION_TYPES